use vstd::prelude::*;

verus! {

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (result: Vec<Vec<i8>>)
    requires
        shape.len() == 2,
        a.len() == shape[0] as nat || a.len() == shape[1] as nat,
    ensures
        result.len() == shape[0] as nat,
        forall|i: int| 0 <= i < result.len() ==> result[i].len() == shape[1] as nat,
        // If a.len() == r (column vector case): result[i][j] == a[i]
        a.len() == shape[0] as nat ==> 
            forall|i: int, j: int| 
                0 <= i < result.len() && 0 <= j < shape[1] as nat ==> 
                result[i][j] == a[i],
        // If a.len() == c (row vector case): result[i][j] == a[j]
        a.len() == shape[1] as nat ==> 
            forall|i: int, j: int| 
                0 <= i < result.len() && 0 <= j < shape[1] as nat ==> 
                result[i][j] == a[j],
{
    // shape has length 2 by problem statement
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    // Length of input array
    let len = a.len();

    // By assumption, len == r or len == c

    // Result matrix: Vec of r rows, each with c elements
    let mut matrix = Vec::with_capacity(r);

    if len == r {
        // Treat `a` as a column vector:
        // each row i is a[i] repeated c times
        let mut i: usize = 0;
        while i < r
            invariant
                r == shape[0] as nat,
                c == shape[1] as nat,
                len == a.len(),
                len == r,
                i <= r,
                matrix.len() == i,
                forall|k: int| 0 <= k < i ==> matrix[k].len() == c,
                forall|k: int, j: int| 
                    0 <= k < i && 0 <= j < c ==> 
                    matrix[k][j] == a[k],
        {
            // replicate a[i] c times
            let row_value = a[i];
            let row = vec![row_value; c];
            assert(row.len() == c);
            assert(forall|j: int| 0 <= j < c ==> row[j] == row_value);
            matrix.push(row);
            i += 1;
        }
    } else {
        // Otherwise, len == c; treat `a` as a row vector:
        // every row is a clone of input array `a`
        let mut i: usize = 0;
        while i < r
            invariant
                r == shape[0] as nat,
                c == shape[1] as nat,
                len == a.len(),
                len == c,
                i <= r,
                matrix.len() == i,
                forall|k: int| 0 <= k < i ==> matrix[k].len() == c,
                forall|k: int, j: int| 
                    0 <= k < i && 0 <= j < c ==> 
                    matrix[k][j] == a[j],
        {
            let cloned = a.clone();
            assert(cloned.len() == a.len());
            assert(forall|j: int| 0 <= j < a.len() ==> cloned[j] == a[j]);
            matrix.push(cloned);
            i += 1;
        }
    }

    matrix
}

}

